node -e "
// Reminder 1: 'Lunch with Jordan tomorrow at 12:30' -> 12:30 PM
// Reminder 2: 'Follow up with Maya if she's not there by 6:30 PM' -> 6:30 PM

// Time gap: 6:30 PM - 12:30 PM = 6 hours
const gapHours = 6;
const gapSeconds = gapHours * 3600;
console.log('Time gap: ' + gapHours + ' hours = ' + gapSeconds + ' seconds');

const baseTs = 1788269400.0;
const newTs = baseTs + gapSeconds;
console.log('Base timestamp: ' + baseTs + ' -> ' + new Date(baseTs * 1000).toUTCString());
console.log('New timestamp:  ' + newTs + ' -> ' + new Date(newTs * 1000).toUTCString());
"

node -e "
const ts = 1788291000;
const d = new Date(ts * 1000);
// Format as ICS datetime string (UTC)
const fmt = s => String(s).padStart(2,'0');
const dtStart = d.getUTCFullYear().toString() +
  fmt(d.getUTCMonth()+1) +
  fmt(d.getUTCDate()) + 'T' +
  fmt(d.getUTCHours()) +
  fmt(d.getUTCMinutes()) +
  fmt(d.getUTCSeconds()) + 'Z';

// End time: 30 min later
const dEnd = new Date((ts + 1800) * 1000);
const dtEnd = dEnd.getUTCFullYear().toString() +
  fmt(dEnd.getUTCMonth()+1) +
  fmt(dEnd.getUTCDate()) + 'T' +
  fmt(dEnd.getUTCHours()) +
  fmt(dEnd.getUTCMinutes()) +
  fmt(dEnd.getUTCSeconds()) + 'Z';

const now = new Date();
const dtStamp = now.getUTCFullYear().toString() +
  fmt(now.getUTCMonth()+1) +
  fmt(now.getUTCDate()) + 'T' +
  fmt(now.getUTCHours()) +
  fmt(now.getUTCMinutes()) +
  fmt(now.getUTCSeconds()) + 'Z';

console.log(dtStart);
console.log(dtEnd);
console.log(dtStamp);
"
